/**
 * Skill extraction: `skillFromTf` turns an `elementum_agentic_skill` block +
 * its tool blocks (delegated to `entities/skill-tool/from-tf.ts`) into the
 * normalized shape `printSkillV2` consumes. Platform ids come only from the
 * stream's import blocks and stay data-side — they never reach printed
 * source. Mirrors `entities/agent/from-tf.ts`.
 */
import { EntityTfError } from "../../engine/entity.js";
import { optionalString, resourceRefLabel } from "../../engine/pull/context.js";
import { scopedLabelToBagKey } from "../../engine/tf/index.js";
import { skillToolFromTf } from "../skill-tool/from-tf.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { analyzeSkillInputCoverage, decomposeSkillInstructions, skillCoverageGapDiagnostics, skillCoverageReportLines, } from "./input-coverage.js";
import { SKILL_RESOURCE_TYPE } from "./module.js";
/** Attributes `skillFromTf` understands — anything else is dialect growth, reported loudly. */
const KNOWN_SKILL_ATTRS = new Set([
    "owner_id",
    "owner_type",
    "name",
    "description",
    "instructions",
    "status",
    "type",
    "properties",
    "routing_priority",
    "aliases",
    "example_utterances",
    "positive_keywords",
    "negative_keywords",
    "depends_on",
]);
/** Dialect attrs with no authoring slot yet — reported by name, skill still pulled. */
const UNAUTHORABLE_SKILL_ATTRS = new Set([
    "user_ids",
    "group_ids",
]);
function optionalStringList(attrs, key, where, ctx) {
    const value = attrs[key];
    if (value === undefined || value === null)
        return undefined;
    if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
        ctx.diagnostics.push(`${where}: ${key} must be a list of strings; dropped`);
        return undefined;
    }
    return value;
}
/**
 * The `elementum_agentic_skill` block + its tool blocks → the normalized
 * skill. Tool blocks belonging to OTHER skills are skipped with a
 * diagnostic (the caller partitions per-skill by skill_id, but stays
 * defensive).
 */
export function skillFromTf(skillBlock, toolBlocks, appLabel, ctx) {
    const label = skillBlock.label;
    if (label === undefined || label === "") {
        throw new EntityTfError(`${SKILL_RESOURCE_TYPE} block is missing its label`);
    }
    const attrs = skillBlock.attrs;
    const name = optionalString(attrs, "name", `skill "${label}"`, ctx) ?? "";
    const where = `skill "${name}" (${SKILL_RESOURCE_TYPE}.${label})`;
    for (const key of Object.keys(attrs)) {
        if (KNOWN_SKILL_ATTRS.has(key))
            continue;
        if (UNAUTHORABLE_SKILL_ATTRS.has(key)) {
            ctx.diagnostics.push(`${where}: ${key} has no authoring slot on the terraform path yet; a rebuilt stream will omit it`);
        }
        else {
            ctx.diagnostics.push(`${where}: unhandled attribute "${key}" — the export dialect grew; extend skillFromTf deliberately`);
        }
    }
    const ownerType = attrs["owner_type"];
    if (ownerType !== "APP_ASPECT") {
        return { skippedReason: `${where}: owner_type ${JSON.stringify(ownerType)} has no terraform-path authoring yet; skipped` };
    }
    if (resourceRefLabel(attrs["owner_id"], APP_RESOURCE_TYPE) !== appLabel) {
        return { skippedReason: `${where}: owner_id does not reference ${APP_RESOURCE_TYPE}.${appLabel}; skipped` };
    }
    let properties;
    const rawProperties = attrs["properties"];
    if (typeof rawProperties === "string" && rawProperties !== "") {
        try {
            properties = JSON.parse(rawProperties);
        }
        catch {
            ctx.diagnostics.push(`${where}: properties is not valid JSON; dropped`);
        }
    }
    const status = optionalString(attrs, "status", where, ctx);
    const routingPriority = attrs["routing_priority"];
    if (routingPriority !== undefined && typeof routingPriority !== "number") {
        ctx.diagnostics.push(`${where}: routing_priority must be a number; dropped`);
    }
    const aliases = optionalStringList(attrs, "aliases", where, ctx);
    const exampleUtterances = optionalStringList(attrs, "example_utterances", where, ctx);
    const positiveKeywords = optionalStringList(attrs, "positive_keywords", where, ctx);
    const negativeKeywords = optionalStringList(attrs, "negative_keywords", where, ctx);
    const discovery = {
        ...(typeof routingPriority === "number" && { routingPriority }),
        ...(aliases !== undefined && { aliases }),
        ...(exampleUtterances !== undefined && { exampleUtterances }),
        ...(positiveKeywords !== undefined && { positiveKeywords }),
        ...(negativeKeywords !== undefined && { negativeKeywords }),
    };
    const owner = { appType: APP_RESOURCE_TYPE, appLabel, ownerTfLabel: appLabel, skillType: SKILL_RESOURCE_TYPE, skillLabel: label };
    const tools = [];
    for (const block of toolBlocks) {
        const tool = skillToolFromTf(block, owner, ctx);
        if (tool !== undefined)
            tools.push(tool);
    }
    const rawInstructions = optionalString(attrs, "instructions", where, ctx) ?? "";
    const coverageTools = tools.map((tool) => ({
        name: tool.name,
        fields: (tool.fields ?? []).flatMap((field) => field.name ?? field.key ?? []),
        inputs: (tool.inputs ?? []).map((input) => input.parameterName),
    }));
    const coverage = analyzeSkillInputCoverage(name, rawInstructions, coverageTools);
    ctx.reports?.push(...skillCoverageReportLines(coverage));
    ctx.diagnostics.push(...skillCoverageGapDiagnostics(coverage));
    const decomposed = decomposeSkillInstructions(rawInstructions);
    const instructions = decomposed.inputs.length > 0 || decomposed.lookups.length > 0
        ? decomposed.prose
        : rawInstructions;
    return {
        skill: {
            refName: scopedLabelToBagKey(appLabel, label),
            name,
            description: optionalString(attrs, "description", where, ctx) ?? "",
            instructions,
            ...(decomposed.inputs.length > 0 && { inputs: decomposed.inputs }),
            ...(decomposed.lookups.length > 0 && { lookups: decomposed.lookups }),
            ...((status === "ACTIVE" || status === "INACTIVE") && { status }),
            ...(properties !== undefined && { properties }),
            ...(Object.keys(discovery).length > 0 && { discovery }),
            tools,
        },
    };
}
